\label{thm:convergence:informal}
    Let Definitions~\ref{def:gd},~\ref{def:factors} and Assumption~\ref{ass:positive_definite} hold, $\delta\in(0, 0.1)$, and $\alpha_{\rm cr}:=C\cdot\omega\lambda N$ with $\omega N=\Theta(1/(L^2 d^{2.5}B^3))$. With probability at least $1-\delta$,
    \begin{align*}
        {\cal L}({\sf T},\mathbb{D}) \le \exp\!\left(-\alpha_{\rm cr}\cdot \frac{\varepsilon^2\, {\sf T}}{\mathsf{N}}\right)\cdot {\cal L}(0,\mathbb{D}),\quad \forall F\in{\cal F}_{\sf M,T,N}(\mathbb{D}).
    \end{align*}
    Equivalently, absorbing $\omega N=\mathrm{poly}(1/L,1/d,1/B)$ into $\bar\alpha:=\mathrm{poly}(L,d,B,\lambda)$, we have ${\cal L}({\sf T})\le \exp(-\bar\alpha\,\varepsilon^2{\sf T}/\mathsf{N})\cdot{\cal L}(0, \mathbb{D})$. The $1/\mathsf{N}$ factor traces to the average-loss convention ${\cal L} = \frac{1}{n}\|{\sf F}-{\sf Y}\|_F^2$ and is essential to the scaling law; see Remark~\ref{rem:n_in_rate}.

\begin{align*}
