    \begin{align}\label{eq:cond_C}
        {\sf C} > \frac{{\sf N}^7\log({\sf N}\cdot Ld/\xi^2)}{\xi^2}.
    \end{align}
    \begin{itemize}
        \item {\it Stage I: Compute-Starved Stage.} If Eq.~\eqref{eq:cond_C} does not hold, the excess risk admits the two-sided bound
        \begin{align*}
            c'\cdot e^{-C_{\rm opt}\sqrt{\kappa}\,\xi^2{\sf C}/{\sf N}^7}\cdot{\cal L}(0,\mathbb{D})\;\le\;\inf_{{\cal F}_{\sf M, T, N}(\mathbb{D})}\sup_{\mathbb{D}\in{\cal D}}\Delta{\cal R}(F)\;\le\;C\cdot e^{-\alpha\,\xi^2{\sf C}/{\sf N}^7}\cdot{\cal L}(0,\mathbb{D}),
        \end{align*}
        where $c', C_{\rm opt}, C, \alpha = \mathrm{poly}(L,d,1/\lambda,1/\omega)$ and $\kappa:=\lambda_{\max}/\lambda\le\mathrm{poly}(L,d,1/\delta)$ is the condition number of the initial kernel: the two exponents agree up to a $\sqrt{\kappa}$ factor.
        \item {\it Stage II: Data-Limited Stage.} If Eq.~\eqref{eq:cond_C} holds, the excess risk follows the matching (up to constants and logarithms) power law
