\label{thm:single_law:informal}
    Let all pre-conditions hold as Corollary~\ref{cor:approximation:informal}. Then, with probability at least $1 - \delta$, there exists:
    \begin{itemize}
        \item {\bf Time-Law.} We fix the dataset size ${\sf N}$ and model size ${\sf M} = \Omega({\sf N}^3)$, and choosing $\varepsilon = \xi/{\sf N}$, we have $\inf_{{\cal F}_{\sf M, T, N}(\mathbb{D})} \sup_{\mathbb{D} \in {\cal D}}  \Delta{\cal R}(F)  \leq \exp(-\alpha\,\xi^2\,{\sf T}/{\sf N}^3) +  O(\frac{\xi^2}{{\sf N}})$, where the ${\sf N}^3$ in the exponent combines the ${\sf N}^2$ from $\varepsilon=\xi/{\sf N}$ with the $1/{\sf N}$ factor in the convergence rate (Remark~\ref{rem:n_in_rate}).
        \item {\bf Data-Law.} For any dataset size ${\sf N}$, we let $\varepsilon = \xi/{\sf N}$, ${\sf M} = \Omega({\sf N}^3)$ and ${\sf T} = \widetilde{\Omega}(\frac{{\sf N}^3}{\xi^2})$, we have: $\inf_{{\cal F}_{\sf M, T, N}(\mathbb{D})} \sup_{\mathbb{D} \in {\cal D}}  \Delta{\cal R}(F)  \leq   O(\frac{\xi^2}{{\sf N}})$.
        \item {\bf Model-Law.} We fix the dataset size ${\sf N}$ and let training time ${\sf T} = \widetilde{\Omega}(\frac{{\sf M}^{2\zeta}{\sf N}}{\xi^2})$, where $\zeta \in (0, 1/3]$. Choosing $\varepsilon = \xi/{\sf M}^{\zeta}$, before the model size ${\sf M}$ is greater than ${\sf N}^{1/\zeta}$, we have $\inf_{{\cal F}_{\sf M, T, N}(\mathbb{D})} \sup_{\mathbb{D} \in {\cal D}} \Delta{\cal R}(F)  \leq \xi^2 {\sf M}^{-\zeta}$.
    \end{itemize}

