\label{lem:helpful_bounds}
    Denote failure probability $\delta \in (0, 0.1)$. Define $B := \max\{O(\sqrt{\log(Nmd/\delta)}), 1\}$. Assuming there exists a constant $R \in (0, 1)$ satisfying $\| w_{(\nu), r}(t) - w_{(\nu), r}(0) \|_2 \leq R$ and $\| U_{(\nu)}(t) - U_{(\nu)}(0)\|_F \leq R$ for $r \in [m]$ and $\nu \in [N]$ and $R \in (0, 1)$.

    We mark the indices as: $r\in [m]$, $p \in [nL]$, $\ell_1, \ell_2 \in [L]$, and $\nu \in [N]$. We denote $i = \lfloor p / L \rfloor$, $\ell = p {\rm ~ mod~} L$, $\ell' \in [\ell]$.

    If Definition~\ref{def:gd} holds, then with a probability at least $1 - \delta$, we have:
    \begin{itemize}
        \item {\rm Basic Bounds.}
        \begin{itemize}
            \item {\bf Part 1.} $\| w_{(\nu), r}(0) \|_2 \leq O(\sqrt{d}B)$.
            \item {\bf Part 2.} $\| U_{(\nu)}(0) \|_F \leq O(dB)$.
            \item {\bf Part 3.} $\| w_{(\nu), r}(t) \|_2 \leq O(\sqrt{d}B)$.
            \item {\bf Part 4.} $\| U_{(\nu)}(t) \|_F \leq O(dB)$.
            \item {\bf Part 5.} $\| \Lambda_{(\nu), i, \ell}(t) \|_2 = \Theta(1)$ for all $\ell \in [L]$.
            \item {\bf Part 6.} $\| \Lambda_{(\nu), i}(t) U_{(\nu)}(t) \Lambda_{(\nu), i}(t)^\top \|_\infty \leq O(dB)$.
            \item {\bf Part 7.} $ \exp\big( [\Lambda_{(\nu), i}(t) U_{(\nu)}(t) \Lambda_{(\nu), i}(t)^\top]_{\ell_1, \ell_2} \big) \in [ \exp(-O(dB)), \exp(O(dB)) ]$ for all $\ell_1, \ell_2 \in [L]$.
            \item {\bf Part 8.} For  $\ell'\in [\ell]$, $ \sigma_{(\nu), p, \ell'}(t) \in [\exp(-O(dB)) / L, 1]$.
        \end{itemize}
        \item {\rm Perturbation Bounds.}
        \begin{itemize}
            \item {\bf Part 9.} $\| w_{(\nu), r}(t) - w_{(\nu), r}(0) \|_2 \leq R$.
            \item {\bf Part 10.} $\| U_{(\nu)}(t) - U_{(\nu)}(0)\|_F \leq R$.
            \item {\bf Part 11.} $\| \Lambda_{(\nu), i, \ell}(t) - \Lambda_{(\nu), i, \ell}(0)\|_2 \leq O(R)$.
            \item {\bf Part 12.} $\| \sigma_{(\nu), p}(t) - \sigma_{(\nu), p}(0) \|_2 \leq O(\sqrt{L}R)$.
            \item {\bf Part 13.} $\| o_{(\nu), p}(t) - o_{(\nu), p}(0) \|_2 \leq O(\sqrt{L}R)$.
        \end{itemize}
        \item {\rm Gradient and Function Norms.}
        \begin{itemize}
            \item {\bf Part 14.} ${\cal L}(t, \mathbb{D}) \leq O(Ld)$.
            \item {\bf Part 15.} $\| \frac{\mathrm{d} {\cal L}(t, \mathbb{D})}{\mathrm{d} \mu_{(\nu)}(t)} \|_F^2 \asymp \frac{\varepsilon^2}{n} \cdot {\cal L}(t, \mathbb{D})$. {\it (Note: the $1/n$ factor is essential and traces directly to the $\frac{1}{n}$ in the loss definition $\mathcal{L} = \frac{1}{n}\|\mathsf{F}-\mathsf{Y}\|_F^2$. See proof below.)}
            \item {\bf Part 16.} $\| \gamma_{(\nu), p}(t) \|_2 \leq o(1/\sqrt{m})$.
        \end{itemize}
    \end{itemize}

    {\bf Proof of Part 1.} Each entry $w_{(\nu),r,k}(0)$ is i.i.d.\ $\mathcal{N}(0,1)$ by initialization. By Fact~\ref{fac:gaussian_tail}, $|w_{(\nu),r,k}(0)| \le C\sqrt{\log(Nmd/\delta)}$ with probability at least $1 - \delta/(Nmd)$. A union bound over $\nu\in[N], r\in[m], k\in[d]$ shows that all entries are bounded by $C\sqrt{\log(Nmd/\delta)}$ simultaneously with probability at least $1-\delta$. Thus $\|w_{(\nu),r}(0)\|_2^2 = \sum_{k\in[d]} w_{(\nu),r,k}(0)^2 \le d \cdot C^2\log(Nmd/\delta) = O(d B^2)$, giving $\|w_{(\nu),r}(0)\|_2 \le O(\sqrt d B)$.

    {\bf Proof of Part 2.} Analogously, each entry $U_{(\nu),k_1,k_2}(0)$ is i.i.d.\ $\mathcal{N}(0,1)$. By Fact~\ref{fac:gaussian_tail} and a union bound over $\nu\in[N], (k_1,k_2)\in[d]\times[d]$, all entries are bounded by $O(B)$ with probability at least $1-\delta$. Therefore $\|U_{(\nu)}(0)\|_F^2 = \sum_{k_1,k_2} U_{(\nu),k_1,k_2}(0)^2 \le d^2\cdot O(B^2) = O(d^2 B^2)$, hence $\|U_{(\nu)}(0)\|_F \le O(dB)$.

    {\bf Proof of Part 3.} By triangle inequality, $\|w_{(\nu),r}(t)\|_2 \le \|w_{(\nu),r}(0)\|_2 + \|w_{(\nu),r}(t)-w_{(\nu),r}(0)\|_2 \le O(\sqrt dB) + R$ from Part~1 and the lemma's hypothesis. Since $R \in (0,1)$ and $B\ge 1$ (so $\sqrt d B\ge 1$), the second summand is dominated and $\|w_{(\nu),r}(t)\|_2 \le O(\sqrt d B)$.

    {\bf Proof of Part 4.} Analogously to Part~3, $\|U_{(\nu)}(t)\|_F \le \|U_{(\nu)}(0)\|_F + \|U_{(\nu)}(t)-U_{(\nu)}(0)\|_F \le O(dB) + R$, and the second summand is dominated by the first under $R\in(0,1)$ and $B\ge 1$, giving $\|U_{(\nu)}(t)\|_F \le O(dB)$.

    {\bf Proof of Part 5.} Because $A_{(\nu)}$ is trained jointly with $W_{(\nu)},U_{(\nu)}$ by gradient flow (Section~\ref{sec:preli}), the entries $a_{(\nu),r,k}(t)$ are no longer in $\{-1,+1\}$ for $t>0$ and are in general not independent of $w_{(\nu),r}(t)$. We therefore prove Part~5 in two steps: first at the initialization time $t=0$ via Hoeffding (where the i.i.d.\ $\pm 1$ assumption holds), then for $t>0$ via the perturbation bound of Part~13 of this lemma and the FFN-drift bound of Lemma~\ref{lem:ffn_drift}.

    {\it Step 1: $\nu=1$ at $t=0$.} The data assumption (Section~\ref{sub:setups}) gives $\|\Lambda_{(0), i, \ell}\|_2 = \|X_{i,\ell}+E_\ell\|_2 = \Theta(1)$ for every $\ell$. Combined with the fact that $\sigma_{(1), p}(0)$ is a probability vector,
    \begin{align*}
        \|o_{(1), p}(0)\|_2 = \|\Lambda_{(0), i}(0)^\top \sigma_{(1), p}(0)\|_2 \le \max_{\ell'} \|\Lambda_{(0), i, \ell'}\|_2 = \Theta(1).
    \end{align*}
    For the $\mu$-term at $t=0$, we note that $a_{(1),r,k}(0) \in \{-1,+1\}$ is i.i.d.\ uniform and independent of $w_{(1),r}(0)\sim\mathcal{N}(0,I_d)$ (the i.i.d.\ initialization ensures this). Hence, fixing $k\in[d]$ and conditioning on $w_{(1),r}(0)$:
    \begin{align*}
        |a_{(1), r, k}(0)\cdot\phi(\langle o_{(1), p}(0), w_{(1), r}(0)\rangle)| & ~ \le 1\cdot\|w_{(1),r}(0)\|_2\cdot\|o_{(1),p}(0)\|_2 \le O(\sqrt{d}B), \\
        {\mathbb{E}}\big[a_{(1), r, k}(0)\cdot\phi(\langle o_{(1), p}(0), w_{(1), r}(0)\rangle)\,\big|\, w_{(1),r}(0)\big] & ~ = {\mathbb{E}}[a_{(1),r,k}(0)]\cdot \phi(\cdot) = 0.
    \end{align*}
    By Hoeffding (Lemma~\ref{lem:hoeffding}) applied to $\sum_{r=1}^m a_{(1),r,k}(0)\phi(\langle o_{(1),p}(0),w_{(1),r}(0)\rangle)$, with probability at least $1-\delta/(md)$:
    \begin{align*}
        \Big|\sum_{r=1}^m a_{(1), r, k}(0)\phi(\langle o_{(1), p}(0), w_{(1), r}(0)\rangle)\Big| \le O(\sqrt{md}B)\sqrt{\log(md/\delta)} \le O(\sqrt{m}\,\sqrt{d}\,B^2).
    \end{align*}
    Taking the union bound over $k\in[d]$:
    \begin{align*}
        \|\mu_{(1), p}(0)\|_2 \le \frac{\omega\sqrt d}{\sqrt m}\max_{k\in[d]}\Big|\sum_r a_{(1),r,k}(0)\phi(\cdot)\Big| \le O(\omega\, d\, B^2),
    \end{align*}
    and therefore
    \begin{align*}
        \|\Lambda_{(1), i, \ell}(0)\|_2 \le \|\Lambda_{(0), i, \ell}(0)\|_2 + \|\mu_{(1), p}(0)\|_2 \le \Theta(1) + O(\omega d B^2) = \Theta(1)\pm o(1/N),
    \end{align*}
    where the last step uses $\omega = o(1/(NdB^2))$ from Definition~\ref{def:gd}.

    {\it Step 2: Extension from $t=0$ to $t>0$.} By Parts~9, 10 and~13 of this lemma (proven below), $\|w_{(1),r}(t)-w_{(1),r}(0)\|_2 \le R$ and $\|o_{(1),p}(t)-o_{(1),p}(0)\|_2 \le O(\sqrt L R)$. By Lemma~\ref{lem:ffn_drift}, $\|A_{(\nu)}(t) - A_{(\nu)}(0)\|_F \le R_A := O(1/(\sqrt m\,\omega\lambda N))$. The Lipschitz expansion of the layer-1 hidden state with respect to $(W,A,o)$ then gives:
    \begin{align*}
        \|\Lambda_{(1), i, \ell}(t) - \Lambda_{(1), i, \ell}(0)\|_2 &\le \frac{\omega}{\sqrt m}\,\Big( \|A_{(1)}(t) - A_{(1)}(0)\|_F\cdot \max_r |\phi(\langle w_{(1),r}(t),o_{(1),p}(t)\rangle)| \\
        &\quad+ \|A_{(1)}(0)\|_F\cdot \big[\max_r \|w_{(1),r}(t)-w_{(1),r}(0)\|_2\cdot \|o_{(1),p}(t)\|_2 + \cdots\big]\Big) \\
        &\le \frac{\omega}{\sqrt m}\big( R_A\cdot O(\sqrt d B) + O(\sqrt{md})\cdot O(R) \big) \\
        &= O\Big(\frac{\omega\sqrt d B}{\sqrt m\,\omega\lambda N}\Big) + O(\omega\sqrt d\, R) = o(1)
    \end{align*}
    under the strengthened width condition of Lemma~\ref{lem:ffn_drift}. Combining with Step~1:
    \begin{align*}
        \|\Lambda_{(1), i, \ell}(t)\|_2 \le \|\Lambda_{(1), i, \ell}(0)\|_2 + o(1) = \Theta(1).
    \end{align*}

    {\it Step 3: Inductive step ($\nu \ge 2$).} Assume the bound holds for layer $\nu-1$. Then $\|\Lambda_{(\nu-1),i,\ell}(t)\|_2 = \Theta(1)$ uniformly in $\ell$ and $t$, hence $\|o_{(\nu),p}(t)\|_2 = \|\Lambda_{(\nu-1),i}(t)^\top\sigma_{(\nu),p}(t)\|_2 \le \max_{\ell'}\|\Lambda_{(\nu-1),i,\ell'}(t)\|_2 = \Theta(1)$. The Hoeffding-then-perturb argument of Steps~1 and~2 applies verbatim to $\mu_{(\nu),p}$ (with all quantities re-indexed to layer $\nu$), giving $\|\Lambda_{(\nu),i,\ell}(t)\|_2 = \Theta(1)$ as claimed. The bound on $\|o_{(\nu),p}(t)\|_2$ follows directly:
    \begin{align}\label{eq:bound_o}
        \|o_{(\nu), p}(t)\|_2 = \Theta(1).
    \end{align}


    {\bf Proof of Part 6.} We have:
    \begin{align*}
        \| \Lambda_{(\nu), i}(t) U_{(\nu)}(t) \Lambda_{(\nu), i}(t)^\top \|_\infty 
        = & ~ \max_{(\ell_1, \ell_2) \in [L] \times [L]}  \left| \Lambda_{(\nu), i, \ell_1}(t)^\top U_{(\nu)}(t) \Lambda_{(\nu), i, \ell_2}(t) \right| \\
        \leq & ~ O(dB)
    \end{align*}
    where the first step follows from simple algebra, the second step follows from Part 4 and Part 5 of this lemma and Cauchy-Schwarz inequality.

    {\bf Proof of Part 7.} From Part~6, $\|\Lambda_{(\nu),i}(t) U_{(\nu)}(t) \Lambda_{(\nu),i}(t)^\top\|_\infty \le O(dB)$, so each attention logit $z_{p,\ell'} := \big[\Lambda_{(\nu),i}(t) U_{(\nu)}(t) \Lambda_{(\nu),i}(t)^\top\big]_{\ell, \ell'}$ satisfies $|z_{p,\ell'}| \le O(dB)$. Therefore $\exp(z_{p,\ell'}) \in [\exp(-O(dB)), \exp(O(dB))]$, which is the claim.

    {\bf Proof of Part 8.} Following Part 7 of this lemma, we can show that:
    \begin{align*}
        \sum_{\ell'\in [\ell]} \exp(\Lambda_{(\nu), i, \ell}(t)^\top U_{(\nu)}(t) \Lambda_{(\nu), i, \ell'}(t)) \le \ell \exp(O(dB)) \le L \exp(O(dB)).
    \end{align*}

    Then we can show that:
    \begin{align*}
        \sigma_{(\nu), p, \ell'}(t) \ge & ~ \exp(\Lambda_{(\nu), i, \ell}(t)^\top U_{(\nu)}(t) \Lambda_{(\nu), i, \ell'}(t)) / \sum_{\ell'\in [\ell]} \exp(\Lambda_{(\nu), i, \ell}(t)^\top U_{(\nu)}(t) \Lambda_{(\nu), i, \ell'}(t)) \\
        \ge & ~ \frac{\exp(-O(dB))}{L \exp(O(dB))} \\
        \ge & ~ \frac{\exp(-O(dB))}{L}.
    \end{align*}
    Combining the previous results, we obtain the result of this part.

    {\bf Proof of Part 9.} This is a direct restatement of the lemma's hypothesis $\|w_{(\nu),r}(t) - w_{(\nu),r}(0)\|_2 \le R$, which is a bootstrapping assumption that is verified self-consistently in Lemma~\ref{lem:perturbations} (where we prove that the gradient flow keeps the iterates inside this ball).

    {\bf Proof of Part 10.} Likewise, this is a direct restatement of the hypothesis $\|U_{(\nu)}(t) - U_{(\nu)}(0)\|_F \le R$, verified self-consistently in Lemma~\ref{lem:perturbations}.

    {\bf Proof of Part 11, 12 and 13.} We proceed by induction on the layer index $\nu$. The base case $\nu=0$ is trivial since $\Lambda_{(0), i, \ell}(t) = X_{i,\ell} + E_\ell$ does not depend on $t$, and so $\Lambda_{(0), i, \ell}(t) = \Lambda_{(0), i, \ell}(0)$.

    {\it Base case: $\nu=1$.} By the definition of $\Lambda_{(1), i, \ell}(t)$ as the $\ell$-th token of layer-1 output:
    \begin{align*}
        & ~ \| \Lambda_{(1), i, \ell}(t) -\Lambda_{(1), i, \ell}(0)\|_2 \\
        = & ~ \sqrt{\sum_{k\in [d]} \left(\frac{\omega}{\sqrt{m}} \cdot \sum_{r=1}^m a_{(1), r, k} \left(\phi(\langle w_{(1), r}(t), o_{(1), p}(t) \rangle) - \phi(\langle w_{(1), r}(0), o_{(1), p}(0) \rangle) \right) \right)^2 },
    \end{align*}
    where the residual connection contributes $\Lambda_{(0), i, \ell}(t) - \Lambda_{(0), i, \ell}(0) = 0$ and the difference reduces to the FFN-after-attention contribution.

    We first bound $\|\sigma_{(1),p}(t)-\sigma_{(1),p}(0)\|_2$ via softmax Lipschitzness. Note that $\sigma_{(1),p}(t)$ is a function of the attention logits $\Lambda_{(0), i}(0) U_{(1)}(t)^\top \Lambda_{(0), i, \ell}(0) \in \mathbb{R}^L$ (here $\Lambda_{(0), i}(t)=\Lambda_{(0), i}(0)$ is fixed). Hence:
    \begin{align*}
        \| \sigma_{(1), p}(t) - \sigma_{(1), p}(0) \|_2
        \leq & ~ O(1) \cdot \| \Lambda_{(0), i}(0) ( U_{(1)}(t) - U_{(1)}(0) )^\top \Lambda_{(0), i, \ell}(0) \|_2 \\
        \leq & ~ O(1) \cdot \|\Lambda_{(0), i}(0)\|_F \cdot \| U_{(1)}(t) - U_{(1)}(0) \|_F \cdot \| \Lambda_{(0), i, \ell}(0) \|_2 \\
        \leq & ~ O(1) \cdot O(\sqrt{L}) \cdot R \cdot O(1) = O(\sqrt{L}R),
    \end{align*}
    where the first step follows from the definition of $\sigma_{(1), p}(t)$ and Fact~\ref{fac:lipschitz_softmax}, the second step from operator-norm submultiplicativity (Cauchy--Schwarz on a quadratic form), the third step from $\|\Lambda_{(0), i}(0)\|_F = O(\sqrt{L})$ (since each token has unit norm, summed over $L$ tokens), $\|U_{(1)}(t) - U_{(1)}(0)\|_F \le R$ (Part 10), and $\|\Lambda_{(0), i, \ell}(0)\|_2 = O(1)$.

    Next, we use the identity $o_{(1),p}(t) = \Lambda_{(0), i}(0)^\top \sigma_{(1), p}(t)$ together with the operator-norm bound $\|\Lambda_{(0),i}(0)\|_{\rm op} = O(1)$ that follows from the per-token unit-norm constraint $\|X_\ell\|_2 = \Theta(1)$ (Section~\ref{sub:setups}) under the residual-and-RMSNorm structure:
    \begin{align*}
        \| o_{(1), p}(t) - o_{(1), p}(0) \|_2 = & ~ \| \Lambda_{(0), i}(0)^\top \big( \sigma_{(1), p}(t) - \sigma_{(1), p}(0) \big) \|_2 \\
        \leq & ~ \|\Lambda_{(0), i}(0)\|_{\rm op} \cdot \| \sigma_{(1), p}(t) - \sigma_{(1), p}(0) \|_2 \\
        \leq & ~ O(1) \cdot O(\sqrt{L}R) = O(\sqrt{L} R),
    \end{align*}
    which matches Part~13.

    For a fixed index $k \in [d]$, we apply Hoeffding's inequality (Lemma~\ref{lem:hoeffding}) to the random variables $a_{(1), r, k} \cdot \big(\phi(\langle w_{(1), r}(t), o_{(1), p}(t) \rangle) - \phi(\langle w_{(1), r}(0), o_{(1), p}(0) \rangle)\big)$ for $r \in [m]$. By Fact~\ref{fac:lipschitz_1} (the ReLU $\phi$ is $1$-Lipschitz):
    \begin{align*}
        & ~ \big| a_{(1), r, k} \cdot \big(\phi(\langle w_{(1), r}(t), o_{(1), p}(t) \rangle) - \phi(\langle w_{(1), r}(0), o_{(1), p}(0) \rangle)\big) \big| \\
        \leq & ~ |a_{(1), r, k}| \cdot \big| \langle w_{(1), r}(t), o_{(1), p}(t) \rangle - \langle w_{(1), r}(0), o_{(1), p}(0) \rangle \big| \\
        \leq & ~ 1 \cdot \big( \| w_{(1), r}(t) - w_{(1), r}(0) \|_2 \cdot \| o_{(1), p}(t) \|_2 + \| w_{(1), r}(0) \|_2 \cdot \| o_{(1), p}(t) - o_{(1), p}(0) \|_2 \big) \\
        \leq & ~ R \cdot O(1) + O(\sqrt{d} B) \cdot O(\sqrt{L} R) \\
        \leq & ~ O(\sqrt{Ld}BR),
    \end{align*}
    where the second step follows from $|a_{(1),r,k}|=1$ and the bilinear difference identity, the third step from the Cauchy--Schwarz inequality together with the perturbation bounds Part 9 and Part 13 of this lemma, the fourth step from $\|w_{(1),r}(0)\|_2\leq O(\sqrt{d}B)$ (Part 1) and $\|o_{(1),p}(t)\|_2 = O(1)$. The mean is zero since $a_{(1), r, k} \in \{-1,+1\}$ uniformly and is independent of $w$:
    \begin{align*}
         {\mathbb{E}}\big[a_{(1), r, k} \cdot \big( \phi(\langle w_{(1), r}(t), o_{(1), p}(t) \rangle) - \phi(\langle w_{(1), r}(0), o_{(1), p}(0) \rangle)\big)\big] =  0.
    \end{align*}
    By Lemma~\ref{lem:hoeffding}, for any fixed $k$, with probability at least $1 - \delta/(md)$:
    \begin{align*}
        &  ~ \Big| \frac{\omega}{\sqrt{m}} \sum_{r=1}^m a_{(1), r, k} \cdot \big(\phi(\langle w_{(1), r}(t), o_{(1), p}(t) \rangle) - \phi(\langle w_{(1), r}(0), o_{(1), p}(0) \rangle)\big) \Big| \\
        & \leq \frac{\omega}{\sqrt{m}}\cdot O(\sqrt{Ld}BR)\cdot\sqrt{m\log(md/\delta)} \\
        & \leq O\Big(\omega \sqrt{Ld}BR\cdot B\Big) = O\big(\omega \sqrt{Ld}B^2R\big).
    \end{align*}
    Choosing $\omega = o(1/(NL^2d^{2.5}B^3))$ as in Definition~\ref{def:gd}, this is bounded by $O(R/(Bd\sqrt{Ld}))$, which is dominated by $R$.

    We therefore get $\| \Lambda_{(1), i, \ell}(t) -\Lambda_{(1), i, \ell}(0)  \|_2 \leq O(R)$ for all $\ell \in [\ell]$ and $\|\Lambda_{(1), i, \ell}(t) -\Lambda_{(1), i, \ell}(0)\|_\infty \leq O(R/\sqrt{d})$.

    When $\nu=2$, we have:
    \begin{align*}
        & ~ \|\sigma_{(2), p} (t) - \sigma_{(2), p} (0) \|_2 \\
        \leq & ~ O(1) \cdot \| \Lambda_{(1), i}(t) U_{(2)}(t)^\top  \Lambda_{(1), i, \ell}(t)  - \Lambda_{(1), i}(0) U_{(2)}(0)^\top  \Lambda_{(1), i, \ell}(0) \|_2 \\
        = & ~ O(1) \cdot \| (\Lambda_{(1), i}(t) \otimes \Lambda_{(1), i, \ell}(t))^\top \mathrm{vec}( U_{(2)}(t)) - (\Lambda_{(1), i}(0) \otimes \Lambda_{(1), i, \ell}(0))^\top \mathrm{vec}( U_{(2)}(0))\|_2 \\
        \leq & ~ O(1) \cdot \Big( \|\Lambda_{(1), i}(t) \otimes \Lambda_{(1), i, \ell}(t)\|_F \cdot O(R) \\
        & ~ \quad\quad ~~~~~~~~~~~~+\| U_{(2)}(0) \|_F \cdot \| \Lambda_{(1), i}(t) \otimes \Lambda_{(1), i, \ell}(t) - \Lambda_{(1), i}(0) \otimes \Lambda_{(1), i, \ell}(0)\|_F\Big) \\
        \leq & ~ O(\sqrt{L}R)
    \end{align*}
    where the first step follows from simple algebra and Fact~\ref{fac:lipschitz_softmax}, the second step follows from a basic tensor trick, the third step follows from the {\it sum} form of the triangle inequality $\|AB - A'B'\|_F \le \|A-A'\|_F \|B\|_F + \|A'\|_F \|B-B'\|_F$ together with Part 4 of this lemma and $\|\Lambda_{(1), i, \ell}(t) -\Lambda_{(1), i, \ell}(0)\|_\infty \leq O(R/(Bd\sqrt{Ld}))$.

    Hence, we have:
    \begin{align*}
        \| o_{(2), i}(t) - o_{(2), i}(0) \|_2 = & ~ \| \Lambda_{(1), i}(t)^\top \sigma_{(2), p}(t) - \Lambda_{(1), i}(0)^\top \sigma_{(2), p}(0) \|_2 \\
        \leq & ~ \| \Lambda_{(1), i}(t) - \Lambda_{(1), i}(0)\|_F \cdot \|\sigma_{(2),p}(t)\|_2 + \| \Lambda_{(1), i}(0)\|_{\rm op} \cdot \|\sigma_{(2),p}(t)-\sigma_{(2),p}(0)\|_2 \\
        \leq & ~ O(\sqrt L R)\cdot O(1) + O(1)\cdot O(\sqrt{L}R) \\
        \leq & ~ O(\sqrt{L}R),
    \end{align*}
    where these steps follow from the {\it sum} triangle inequality $\|AB-A'B'\|\le \|A-A'\|\|B\| + \|A'\|\|B-B'\|$, Fact~\ref{fac:lipschitz_softmax} for the softmax bound, and Part 10 of this Lemma.

    To extend $\|\Lambda_{(2),i,\ell}(t)-\Lambda_{(2),i,\ell}(0)\|_2$ from a $\nu=2$-specific bound to the inductive step, we apply the same two-step argument as in Part~5. At $t=0$, $a_{(2),r,k}(0)\in\{-1,+1\}$ is i.i.d.\ uniform and independent of $w_{(2),r}(0)$, so Hoeffding's inequality (Lemma~\ref{lem:hoeffding}) bounds the i.i.d.\ component as $O(\sqrt{m}\sqrt{d}B^2)$ with high probability; for $t>0$, the difference $\Lambda_{(2),i,\ell}(t)-\Lambda_{(2),i,\ell}(0)$ contains contributions from $w_{(2)}$, $U_{(2)}$, $A_{(2)}$ drift, each bounded by $R$, $R$, $R_A$ respectively (from Parts~9, 10 of this lemma and Lemma~\ref{lem:ffn_drift}). The Lipschitz expansion in $(W, U, A)$ yields:
    \begin{align*}
        \|\Lambda_{(2),i,\ell}(t)-\Lambda_{(2),i,\ell}(0)\|_2 \le O(\sqrt L R) + O(\omega \sqrt d B \cdot R_A) = O(\sqrt L R),
    \end{align*}
    where the second equality uses the strengthened width condition of Lemma~\ref{lem:ffn_drift} so that the $A$-drift term is dominated by the $W,U$-drift.

    By induction (using the same two-step Hoeffding-then-perturb argument at each layer), we obtain the bounds of Parts~11, 12, and 13.

    {\bf Proof of Part 14.}
    We have:
    \begin{align*}
        {\cal L}(t, \mathbb{D}) = & ~ \frac{1}{n} \| {\sf F}(t) - {\sf Y} \|_F^2 \\
        \leq & ~ L\max_{p \in [nL]} \| {\sf F}_p(t) - {\sf Y}_p \|_2^2 \\
        \leq & ~ L\max_{p \in [nL]} \left( \| {\sf F}_p(t)\|_2 +  \| {\sf Y}_p \|_2 \right)^2 \\
        \leq & ~ L \left( O(1) + O(\sqrt{d}) \right)^2 \\
        \leq & ~ O(Ld),
    \end{align*}
    where the first step follows from Lemma~\ref{lem:compact_form_transform}, the second step follows from simple algebras, the third step follows from the Cauchy-Schwartz inequality, the last two steps follow from Definition~\ref{def:D} and simple algebras.

    {\bf Proof of Part 15.}
    We show that $\|\frac{\mathrm{d} {\cal L}(t,\mathbb{D})}{\mathrm{d}\mu_{(\nu)}(t)}\|_F^2 \asymp \frac{\varepsilon^2}{n} \cdot {\cal L}(t,\mathbb{D})$ by reverse induction on $\nu$ from $N$ down to $1$. The $1/n$ factor in the bound is essential and traceable to the $1/n$ in the definition $\mathcal{L} = \frac{1}{n}\|\mathsf{F}-\mathsf{Y}\|_F^2$ of the average training loss (see the base case below).

    {\it Base case: $\nu = N$.} By Part 3 of Lemma~\ref{lem:grad_computation}, $\frac{\mathrm{d}{\cal L}(t,\mathbb{D})}{\mathrm{d} \mu_{(N), p}(t)} = \frac{2\varepsilon}{n}({\sf F}_p(t)-{\sf Y}_p)$ since $G_{(N),p}(t) = {\bf 0}_d$. Hence:
    \begin{align*}
        \Big\|\frac{\mathrm{d}{\cal L}(t,\mathbb{D})}{\mathrm{d} \mu_{(N)}(t)}\Big\|_F^2
        = \frac{4\varepsilon^2}{n^2}\sum_p \|{\sf F}_p(t)-{\sf Y}_p\|_2^2
        = \frac{4\varepsilon^2}{n}\cdot {\cal L}(t,\mathbb{D}),
    \end{align*}
    using $\sum_p \|\mathsf{F}_p-\mathsf{Y}_p\|_2^2 = n\,\mathcal{L}(t,\mathbb{D})$ from Lemma~\ref{lem:compact_form_transform}. This establishes $\|\frac{\mathrm{d}{\cal L}}{\mathrm{d}\mu_{(N)}}\|_F^2 \le 4\varepsilon^2 \mathcal{L}/n \le O(\varepsilon^2 Ld/n)$ via Part~14, hence $\|\frac{\mathrm{d}{\cal L}}{\mathrm{d}\mu_{(N)}}\|_F \le O(\varepsilon\sqrt{Ld/n})$.

    {\it Inductive step.} Assume the claim for layer $\nu+1$. We bound the auxiliary term $G_{(\nu),p}(t)$ (Part~3 of Lemma~\ref{lem:grad_computation}). The factor $\kappa U_{(\nu)}(t) \Lambda_{(\nu-1),i}(t)^\top \mathrm{diag}({\bf 1}_n - \frac{1}{2}e_\ell) (\mathrm{diag}\sigma - \sigma\sigma^\top)\Lambda_{(\nu-1),i}(t)$ is bounded by:
    \begin{align*}
        & ~ \big\| \kappa U_{(\nu)}(t)\Lambda_{(\nu-1), i }(t)^\top \mathrm{diag}({\bf 1}_n - \tfrac{1}{2}e_\ell) (\mathrm{diag}\sigma_{(\nu), p}(t) - \sigma_{(\nu), p}(t)\sigma_{(\nu), p}(t)^\top)\Lambda_{(\nu-1), i }(t) \big\|_F \\
        \leq & ~ \kappa \cdot \|U_{(\nu)}(t)\|_F \cdot \|\Lambda_{(\nu-1),i}(t)\|_F^2 \cdot O(1) \\
        \leq & ~ \kappa \cdot O(dB) \cdot O(L) \cdot O(1) \\
        = & ~ O(\kappa L^2dB) \leq O(L^2dB),
    \end{align*}
    where we use Parts 4 and 5, the fact that $\mathrm{diag}\sigma - \sigma\sigma^\top$ has spectral norm at most $1$, and $\kappa = 1/\sqrt{m} \leq 1$.

    To bound the random sum $\sum_{r\in[m]} a_{(\nu),r}(t)\langle\frac{\mathrm{d}{\cal L}}{\mathrm{d}\mu_{(\nu+1),p}}, a_{(\nu),r}(t)\rangle\, w_{(\nu),r}(t)\,\mathbb{I}\{\cdot\}$, we again apply Hoeffding {\it at $t=0$} (where $a_{(\nu),r,k}(0)\in\{-1,+1\}$ is i.i.d.\ and independent of $w_{(\nu),r}(0)$) to obtain $\|G_{(\nu),p}(0)\|_2^2 \le \omega\cdot O(L^2 d^{2.5} B^3)$, and then propagate to $t>0$ via the $A$-drift bound $\|A_{(\nu)}(t)-A_{(\nu)}(0)\|_F \le R_A$ from Lemma~\ref{lem:ffn_drift} and the $W$-drift bound $\|w_{(\nu),r}(t)-w_{(\nu),r}(0)\|_2 \le R$ from Part~9 of this lemma:
    \begin{align*}
        \|G_{(\nu),p}(t)\|_2 \le \|G_{(\nu),p}(0)\|_2 + O(\omega\sqrt{m}\,\|A_{(\nu)}(t)-A_{(\nu)}(0)\|_F + \omega\sqrt{m d}\,R) = O(\sqrt\omega \cdot Ld^{1.25}B^{1.5}),
    \end{align*}
    so that $\|G_{(\nu),p}(t)\|_2^2 \le \omega\cdot O(L^2 d^{2.5}B^3) \le o(1)$ under Definition~\ref{def:gd}'s choice $\omega = o(1/(NL^2 d^{2.5}B^3))$ and the strengthened width of Lemma~\ref{lem:ffn_drift}.

    Therefore $I_d + \mathrm{diag}(G_{(\nu),p}(t)) = (1\pm o(1))I_d$, and by Part~3 of Lemma~\ref{lem:grad_computation}:
    \begin{align*}
