\label{thm:single_law}
    Let all pre-conditions hold as Corollary~\ref{cor:approximation}. Then, with a probability at least $1 - \delta$, there exists:
    \begin{itemize}
        \item {\bf Time-Law.} We fix the dataset set ${\sf N}$ and model size ${\sf M} = \Omega({\sf N}^3)$, and choosing $\varepsilon = \xi/{\sf N}$, we have $\inf_{{\cal F}_{\sf M, T, N}(\mathbb{D})} \sup_{\mathbb{D} \in {\cal D}}  \Delta{\cal R}(F)  \leq \exp(-\alpha\,\xi^2\,{\sf T}/{\sf N}^3) +  O(\frac{\xi^2}{{\sf N}} )$.
        \item {\bf Data-Law.} For any dataset size ${\sf N}$, we let $\varepsilon = \xi/{\sf N}$, ${\sf M} = \Omega({\sf N}^3)$ and $T = \widetilde{\Omega}(\frac{{\sf N}^3\log({\sf N}\cdot Ld/\xi^2)}{\xi^2})$, we have: $\inf_{{\cal F}_{\sf M, T, N}(\mathbb{D})} \sup_{\mathbb{D} \in {\cal D}}  \Delta{\cal R}(F)  \leq   O(\frac{\xi^2}{{\sf N}} )$.
        \item {\bf Model-Law.} We fix the dataset set ${\sf N}$ and let training time $T = \widetilde{\Omega}(\frac{{\sf M}^{2\zeta}\mathsf{N}\log({\sf N}\cdot Ld/\xi^2)}{\xi^2})$, where $\zeta \in (0, 1/3]$. Choosing $\varepsilon = \xi/{\sf M}^{\zeta}$, in the regime ${\sf N}^3 \le {\sf M} \le {\sf N}^{1/\zeta}$, we have $\inf_{{\cal F}_{\sf M, T, N}(\mathbb{D})} \sup_{\mathbb{D} \in {\cal D}} $ $ \Delta{\cal R}(F)  \leq \xi^2 {\sf M}^{-\zeta}$.
    \end{itemize}

\label{thm:lower_stat}
    Let $K$ be the layer-aggregated NTK at initialization, $K(x,y):=\sum_{\nu\in[N]}H_{(\nu),x,y}(0)$, and $\mathcal{H}_K$ its associated RKHS. Suppose there exists a non-zero element $g\in {\cal H}_K$ with $\|g\|_{L^F({\cal X})}>0$. Assume the noise $\Xi$ has each token-coordinate $\Xi_{\ell, k}$ Gaussian with variance $\xi^2$ (the standard sub-Gaussian assumption strengthens this to a constant factor; see Remark~\ref{rem:non_gaussian}). Let $\widehat F := \widehat F(\mathbb{D})$ denote any (deterministic or randomized) measurable estimator of $F^*$ from a dataset $\mathbb{D}$ of size $\sf N$. Then there exist absolute constants $c_1, c_2>0$ such that:
    \begin{align*}
        \inf_{\widehat F} \sup_{F^*\in {\cal H}_K} {\mathbb{E}}_{\mathbb{D}\sim {\cal D}^{\otimes {\sf N}}}\big[\Delta{\cal R}(\widehat F)\big] \ge c_1 \cdot \frac{\xi^2}{{\sf N}}.
    \end{align*}

\begin{align*}
        \inf_{\widehat F} \sup_{F^*\in {\cal H}_K} {\mathbb{E}}_{\mathbb{D}\sim {\cal D}^{\otimes {\sf N}}}\big[\Delta{\cal R}(\widehat F)\big] \ge c_1 \cdot \frac{\xi^2}{{\sf N}}.
    \end{align*}

\textbf{Step 1: Two-point construction.} Let $g\in {\cal H}_K$ be the non-zero element fixed by hypothesis, normalized so that $\|g\|_{L^F({\cal X})}=1$. Define the two-point family:
\begin{align*}
    F_0^* := 0, \qquad F_1^* := \rho \cdot g, \qquad \rho := \sqrt{\frac{\xi^2}{2{\sf N}}}.
\end{align*}
Both lie in ${\cal H}_K$.

\textbf{Step 2: Bound the KL divergence.} Under each $F_j^*$, the data law is $\mathcal{D}_j = {\cal X}\times \mathcal{N}(F_j^*(X), \xi^2 I_{Ld})$, so the per-sample KL divergence is
\begin{align*}
    D_{\rm KL}({\cal D}_0\|{\cal D}_1) = {\mathbb{E}}_X\Big[\frac{1}{2\xi^2}\|F_0^*(X) - F_1^*(X)\|_F^2\Big] = \frac{\rho^2}{2\xi^2} \cdot \|g\|_{L^F({\cal X})}^2 = \frac{\rho^2}{2\xi^2}.
\end{align*}
For an i.i.d.\ dataset of size $\sf N$, $D_{\rm KL}({\cal D}_0^{\otimes {\sf N}}\|{\cal D}_1^{\otimes {\sf N}}) = {\sf N}\cdot \rho^2/(2\xi^2)$. With our choice $\rho^2 = \xi^2/(2{\sf N})$, we have:
\begin{align*}
    D_{\rm KL}({\cal D}_0^{\otimes {\sf N}}\|{\cal D}_1^{\otimes {\sf N}}) = \frac{1}{4} \le \log 2.
\end{align*}

\textbf{Step 3: Apply Le Cam's two-point lemma} (Theorem 2.2 of \citealp{tsy09}). For any estimator $\widehat F$:
\begin{align*}
    \inf_{\widehat F}\sup_{j\in\{0,1\}} {\mathbb{E}}_{\mathbb{D}\sim {\cal D}_j^{\otimes{\sf N}}}\big[\|\widehat F-F_j^*\|_{L^F({\cal X})}^2\big] \ge \frac{1}{4}\big(1-\sqrt{D_{\rm KL}/2}\big)\cdot \|F_0^*-F_1^*\|_{L^F({\cal X})}^2.
\end{align*}
Substituting the bound on KL:
\begin{align*}
    \inf_{\widehat F}\sup_{j\in\{0,1\}} {\mathbb{E}}\big[\|\widehat F-F_j^*\|_{L^F({\cal X})}^2\big] \ge \frac{1}{4}\big(1 - \sqrt{1/8}\big)\cdot \rho^2 \ge \frac{1}{8}\cdot \frac{\xi^2}{2{\sf N}} = \frac{\xi^2}{16{\sf N}}.
\end{align*}

\textbf{Step 4: Translate to excess risk.} By Equation~\eqref{eq:bound_delta_R}, $\Delta{\cal R}(F) = \|F - F^*\|_{L^F({\cal X})}^2$, so:
\begin{align*}
    \inf_{\widehat F}\sup_{F^*\in{\cal H}_K} {\mathbb{E}}\big[\Delta{\cal R}(\widehat F)\big] \ge \inf_{\widehat F}\sup_{j\in\{0,1\}} {\mathbb{E}}\big[\Delta{\cal R}(\widehat F)\big] \ge \frac{\xi^2}{16{\sf N}},
\end{align*}
yielding the claim with $c_1 = 1/16$.

\begin{align*}
        F_0^* := 0, \qquad F_1^* := \rho \cdot g, \qquad \rho := \sqrt{\frac{\xi^2}{2{\sf N}}}.
    \end{align*}

\begin{align*}
        D_{\rm KL}({\cal D}_0\|{\cal D}_1) = {\mathbb{E}}_X\Big[\frac{1}{2\xi^2}\|F_0^*(X) - F_1^*(X)\|_F^2\Big] = \frac{\rho^2}{2\xi^2} \cdot \|g\|_{L^F({\cal X})}^2 = \frac{\rho^2}{2\xi^2}.
    \end{align*}

\begin{align*}
        D_{\rm KL}({\cal D}_0^{\otimes {\sf N}}\|{\cal D}_1^{\otimes {\sf N}}) = \frac{1}{4} \le \log 2.
    \end{align*}

\begin{align*}
        \inf_{\widehat F}\sup_{j\in\{0,1\}} {\mathbb{E}}_{\mathbb{D}\sim {\cal D}_j^{\otimes{\sf N}}}\big[\|\widehat F-F_j^*\|_{L^F({\cal X})}^2\big] \ge \frac{1}{4}\big(1-\sqrt{D_{\rm KL}/2}\big)\cdot \|F_0^*-F_1^*\|_{L^F({\cal X})}^2.
    \end{align*}

\begin{align*}
        \inf_{\widehat F}\sup_{j\in\{0,1\}} {\mathbb{E}}\big[\|\widehat F-F_j^*\|_{L^F({\cal X})}^2\big] \ge \frac{1}{4}\big(1 - \sqrt{1/8}\big)\cdot \rho^2 \ge \frac{1}{8}\cdot \frac{\xi^2}{2{\sf N}} = \frac{\xi^2}{16{\sf N}}.
    \end{align*}

\begin{align*}
        \inf_{\widehat F}\sup_{F^*\in{\cal H}_K} {\mathbb{E}}\big[\Delta{\cal R}(\widehat F)\big] \ge \inf_{\widehat F}\sup_{j\in\{0,1\}} {\mathbb{E}}\big[\Delta{\cal R}(\widehat F)\big] \ge \frac{\xi^2}{16{\sf N}},
    \end{align*}

